function check([numArrows, aliceArrows], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== 12) return false;
  if (actual.some(v => !Number.isInteger(v) || v < 0)) return false;
  if (actual.reduce((sum, v) => sum + v, 0) !== numArrows) return false;
  const score = (bob) => bob.reduce((sum, v, k) => sum + (v > aliceArrows[k] ? k : 0), 0);
  return score(actual) === score(expected);
}

