function maximumBobPoints(numArrows, aliceArrows) {
  let bestScore = -1;
  let bestMask = 0;
  for (let mask = 0; mask < 1 << 12; mask++) {
    let arrows = 0;
    let score = 0;
    for (let k = 0; k < 12; k++) {
      if (mask & (1 << k)) {
        arrows += aliceArrows[k] + 1;
        score += k;
      }
    }
    if (arrows <= numArrows && score > bestScore) {
      bestScore = score;
      bestMask = mask;
    }
  }
  const bobArrows = new Array(12).fill(0);
  let remaining = numArrows;
  for (let k = 0; k < 12; k++) {
    if (bestMask & (1 << k)) {
      bobArrows[k] = aliceArrows[k] + 1;
      remaining -= bobArrows[k];
    }
  }
  bobArrows[0] += remaining;
  return bobArrows;
}

