function maximumBobPoints(numArrows, aliceArrows) {
  // dp[k][a]: the most points Bob can take from sections k..11 with a arrows to spend.
  const dp = Array.from({ length: 13 }, () => new Array(numArrows + 1).fill(0));
  for (let k = 11; k >= 0; k--) {
    for (let a = 0; a <= numArrows; a++) {
      dp[k][a] = dp[k + 1][a];
      const need = aliceArrows[k] + 1;
      if (need <= a) dp[k][a] = Math.max(dp[k][a], dp[k + 1][a - need] + k);
    }
  }
  const bob = new Array(12).fill(0);
  let left = numArrows;
  for (let k = 0; k < 12; k++) {
    if (dp[k][left] !== dp[k + 1][left]) {
      bob[k] = aliceArrows[k] + 1;
      left -= bob[k];
    }
  }
  bob[0] += left;
  return bob;
}

