function generate(rand, size) {
  const numArrows = size === 'large' ? 1 + Math.floor(rand() * 100000) : 1 + Math.floor(rand() * 15);
  const chance = 0.2 + rand() * 0.8;
  const hot = [];
  for (let k = 0; k < 12; k++) if (rand() < chance) hot.push(k);
  if (hot.length === 0) hot.push(Math.floor(rand() * 12));
  const aliceArrows = new Array(12).fill(0);
  if (size === 'large') {
    let left = numArrows;
    for (let i = 0; i < hot.length - 1; i++) {
      const part = Math.floor(rand() * (left + 1) * 0.6);
      aliceArrows[hot[i]] += part;
      left -= part;
    }
    aliceArrows[hot[hot.length - 1]] += left;
  } else {
    for (let i = 0; i < numArrows; i++) aliceArrows[hot[Math.floor(rand() * hot.length)]]++;
  }
  return [numArrows, aliceArrows];
}
